public static class RebirthNativeItemCodec{public static string Encode(ItemValue value){using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(value.type);writer.Write(value.Quality);writer.Write(value.Seed);writer.Write(value.HasModSlots);writer.Write(value.Mods);foreach(var mod in value.Modifications)writer.Write(mod);foreach(var pair in value.Metadata){writer.Write(pair.Key);writer.Write(pair.Value);}writer.Flush();return Convert.ToBase64String(stream.ToArray());}}}
