public static class PaymentCases
{
 static ItemStack[] Copy(ItemStack[] slots){var result=new ItemStack[slots.Length];for(int i=0;i<slots.Length;i++)result[i]=slots[i].Clone();return result;}
 static bool Case(ItemStack[] bag,ItemStack[] belt,List<ItemStack> demand,int batches)
 {
  string before,untouched;if(!RebirthTheorySoloNativePaymentPlan.TryHash(bag,belt,out before))throw new Exception("Before shape");
  bool planned=RebirthTheorySoloNativePaymentPlan.TryCreate(demand,batches,bag,belt,out var plan);RebirthTheorySoloNativePaymentPlan.TryHash(bag,belt,out untouched);if(before!=untouched)throw new Exception("Plan mutated native source");if(!planned)return false;
  var nativeBag=new NativeBag{itemGrid=Copy(bag)};var nativeBelt=new NativeInventory{itemGrid=Copy(belt)};var removed=new List<ItemStack>();foreach(var item in demand){int needed=item.count*batches;needed-=nativeBag.DecItem(item.itemValue,needed,true,removed);if(needed>0)needed-=nativeBelt.DecItem(item.itemValue,needed,true,removed);if(needed!=0)throw new Exception("Native shortage");}
  string after;RebirthTheorySoloNativePaymentPlan.TryHash(nativeBag.itemGrid,nativeBelt.itemGrid,out after);if(after!=plan.AfterHash)throw new Exception("Actual native debit mismatch");var paid=plan.PaidSnapshot();if(paid.Count!=removed.Count)throw new Exception("Actual removed count");for(int i=0;i<paid.Count;i++)if(paid[i].count!=removed[i].count||RebirthNativeItemCodec.Encode(paid[i].itemValue)!=RebirthNativeItemCodec.Encode(removed[i].itemValue))throw new Exception("Actual removed quality/metadata");return true;
 }
 static ItemStack Stack(int type,int count,int quality=6,bool mods=false){return new ItemStack(new ItemValue{type=count==0?0:type,Quality=quality,HasModSlots=mods,Mods=mods},count);}
 public static bool Run(){if(!Case(new[]{Stack(1,2),Stack(1,3)},new[]{Stack(1,4)},new List<ItemStack>{Stack(1,3)},2))throw new Exception("Split debit");if(!Case(new[]{Stack(2,1,4,true),Stack(2,1,5)},new[]{Stack(2,1,7)},new List<ItemStack>{Stack(2,1)},2))throw new Exception("Quality debit");if(Case(new[]{Stack(1,1)},new[]{Stack(1,1)},new List<ItemStack>{Stack(1,3)},1))throw new Exception("Shortage accepted");if(!Case(new[]{Stack(1,6)},new ItemStack[0],new List<ItemStack>{Stack(1,1),Stack(1,1)},2))throw new Exception("Repeated ingredient");var rng=new Random(2917);int qualified=0;for(int n=0;n<200;n++){var bag=new ItemStack[6];var belt=new ItemStack[4];for(int i=0;i<bag.Length;i++)bag[i]=Stack(1,rng.Next(0,6),rng.Next(1,7),rng.Next(0,4)==0);for(int i=0;i<belt.Length;i++)belt[i]=Stack(1,rng.Next(0,6),rng.Next(1,7),rng.Next(0,4)==0);if(Case(bag,belt,new List<ItemStack>{Stack(1,rng.Next(1,4))},rng.Next(1,4)))qualified++;}if(qualified<100)throw new Exception("Insufficient native comparisons");Console.WriteLine("Actual installed native Bag/Inventory debit equivalence: "+qualified+" random cases plus4 targeted cases");return true;}
}
